/**
 * Complexity Analyzer
 *
 * AST-based code complexity analysis using oxc-parser.
 * Replaces regex-based complexity calculation in engine/risk-score.ts.
 *
 * Calculates per-function and per-file metrics:
 * - Cyclomatic complexity (branches, loops, ternaries, logical operators)
 * - Cognitive complexity (nesting penalty + structural complexity)
 * - Maximum nesting depth
 * - Function count
 * - Parameter count
 *
 * Returns AnalysisIssues for functions exceeding complexity thresholds.
 *
 * @module analysis/ast/ComplexityAnalyzer
 */

import type { AnalysisContext, AnalysisIssue, Analyzer, AnalyzerResult } from "../types.js";
import { isSupportedFile, type OxcNode, parseSource, walkAST } from "./parser.js";

/** Thresholds for flagging complexity issues */
const THRESHOLDS = {
	/** Cyclomatic complexity per function */
	maxCyclomaticPerFunction: 15,
	/** Maximum nesting depth per function */
	maxNestingDepth: 5,
	/** Maximum parameters per function */
	maxParameters: 5,
	/** Maximum functions per file */
	maxFunctionsPerFile: 30,
	/** File-level aggregate cyclomatic complexity */
	maxCyclomaticPerFile: 50,
};

/** Complexity metrics for a single function */
export interface FunctionComplexity {
	name: string;
	line: number;
	cyclomatic: number;
	maxNesting: number;
	parameters: number;
}

/** Complexity metrics for a file */
export interface FileComplexity {
	filePath: string;
	functions: FunctionComplexity[];
	totalCyclomatic: number;
	maxNesting: number;
	functionCount: number;
	averageCyclomatic: number;
}

/** Node types that increment cyclomatic complexity */
const BRANCH_NODES = new Set([
	"IfStatement",
	"ConditionalExpression",
	"SwitchCase",
	"ForStatement",
	"ForInStatement",
	"ForOfStatement",
	"WhileStatement",
	"DoWhileStatement",
	"CatchClause",
]);

/** Node types that contribute to logical branching */
const LOGICAL_OPERATORS = new Set(["&&", "||", "??"]);

/** Node types that represent function declarations */
const FUNCTION_NODES = new Set([
	"FunctionDeclaration",
	"FunctionExpression",
	"ArrowFunctionExpression",
	"MethodDefinition",
]);

/**
 * AST-based complexity analyzer.
 * Implements the Analyzer interface for the analysis pipeline.
 */
export class ComplexityAnalyzer implements Analyzer {
	readonly id = "complexity";
	readonly name = "Complexity Analysis";
	readonly filePatterns = ["*.ts", "*.tsx", "*.js", "*.jsx"];

	async analyze(context: AnalysisContext): Promise<AnalyzerResult> {
		const startTime = performance.now();
		const issues: AnalysisIssue[] = [];
		let filesAnalyzed = 0;
		let totalNodesVisited = 0;
		const parseErrors: string[] = [];

		for (const [file, content] of context.contents) {
			if (!this.shouldAnalyzeFile(file)) {
				continue;
			}
			filesAnalyzed++;

			const fileComplexity = this.analyzeFile(content, file);

			if (!fileComplexity) {
				parseErrors.push(`${file}: Failed to parse`);
				continue;
			}

			totalNodesVisited += fileComplexity.functions.length;

			// Check per-function thresholds
			for (const fn of fileComplexity.functions) {
				if (fn.cyclomatic > THRESHOLDS.maxCyclomaticPerFunction) {
					issues.push({
						id: `complexity/cyclomatic/${file}/${fn.line}`,
						severity: fn.cyclomatic > THRESHOLDS.maxCyclomaticPerFunction * 2 ? "high" : "medium",
						type: "HIGH_CYCLOMATIC_COMPLEXITY",
						message: `Function "${fn.name}" has cyclomatic complexity ${fn.cyclomatic} (max: ${THRESHOLDS.maxCyclomaticPerFunction})`,
						file,
						line: fn.line,
						fix: "Extract helper functions or simplify branching logic",
					});
				}

				if (fn.maxNesting > THRESHOLDS.maxNestingDepth) {
					issues.push({
						id: `complexity/nesting/${file}/${fn.line}`,
						severity: "medium",
						type: "DEEP_NESTING",
						message: `Function "${fn.name}" has nesting depth ${fn.maxNesting} (max: ${THRESHOLDS.maxNestingDepth})`,
						file,
						line: fn.line,
						fix: "Use early returns or extract nested logic into helper functions",
					});
				}

				if (fn.parameters > THRESHOLDS.maxParameters) {
					issues.push({
						id: `complexity/parameters/${file}/${fn.line}`,
						severity: "low",
						type: "TOO_MANY_PARAMETERS",
						message: `Function "${fn.name}" has ${fn.parameters} parameters (max: ${THRESHOLDS.maxParameters})`,
						file,
						line: fn.line,
						fix: "Use an options object pattern to reduce parameter count",
					});
				}
			}

			// Check file-level thresholds
			if (fileComplexity.functionCount > THRESHOLDS.maxFunctionsPerFile) {
				issues.push({
					id: `complexity/function-count/${file}`,
					severity: "low",
					type: "TOO_MANY_FUNCTIONS",
					message: `${file} has ${fileComplexity.functionCount} functions (max: ${THRESHOLDS.maxFunctionsPerFile})`,
					file,
					fix: "Split into multiple focused modules",
				});
			}

			if (fileComplexity.totalCyclomatic > THRESHOLDS.maxCyclomaticPerFile) {
				issues.push({
					id: `complexity/file-complexity/${file}`,
					severity: "medium",
					type: "HIGH_FILE_COMPLEXITY",
					message: `${file} has total cyclomatic complexity ${fileComplexity.totalCyclomatic} (max: ${THRESHOLDS.maxCyclomaticPerFile})`,
					file,
					fix: "Consider splitting this file into smaller modules",
				});
			}
		}

		return {
			analyzer: this.id,
			success: true,
			issues,
			coverage: filesAnalyzed / Math.max(context.files.length, 1),
			duration: performance.now() - startTime,
			metadata: {
				filesAnalyzed,
				nodesVisited: totalNodesVisited,
				patternsChecked: [
					"HIGH_CYCLOMATIC_COMPLEXITY",
					"DEEP_NESTING",
					"TOO_MANY_PARAMETERS",
					"TOO_MANY_FUNCTIONS",
					"HIGH_FILE_COMPLEXITY",
				],
				parseErrors,
			},
		};
	}

	shouldRun(context: AnalysisContext): boolean {
		return context.files.some((f) => this.shouldAnalyzeFile(f));
	}

	/**
	 * Analyze a single file and return complexity metrics.
	 * Useful for external callers that just want metrics, not issues.
	 */
	analyzeFile(content: string, filePath: string): FileComplexity | null {
		if (!isSupportedFile(filePath)) {
			return null;
		}

		const { program, success } = parseSource(content, filePath);
		if (!success && program.body.length === 0) {
			return null;
		}

		const functions: FunctionComplexity[] = [];
		let fileMaxNesting = 0;

		// Find all function nodes and compute per-function metrics
		walkAST(program, (node: OxcNode) => {
			if (!FUNCTION_NODES.has(node.type)) {
				return;
			}

			const fn = this.analyzeFunctionNode(node);
			functions.push(fn);
			if (fn.maxNesting > fileMaxNesting) {
				fileMaxNesting = fn.maxNesting;
			}
		});

		const totalCyclomatic = functions.reduce((sum, fn) => sum + fn.cyclomatic, 0);

		return {
			filePath,
			functions,
			totalCyclomatic,
			maxNesting: fileMaxNesting,
			functionCount: functions.length,
			averageCyclomatic: functions.length > 0 ? totalCyclomatic / functions.length : 0,
		};
	}

	// -----------------------------------------------------------------------
	// Per-function analysis
	// -----------------------------------------------------------------------

	private analyzeFunctionNode(node: OxcNode): FunctionComplexity {
		const name = this.getFunctionName(node);
		const line = node.start ?? 0;
		const params = this.getParameterCount(node);

		// Cyclomatic complexity: start at 1 (base path)
		let cyclomatic = 1;
		let maxNesting = 0;

		// Walk the function body
		const body = this.getFunctionBody(node);
		if (body) {
			this.walkForComplexity(body, (n, depth) => {
				// Increment cyclomatic for branch nodes
				if (BRANCH_NODES.has(n.type)) {
					cyclomatic++;
				}

				// Check for logical operators (&&, ||, ??)
				if (n.type === "LogicalExpression") {
					const operator = n.operator as string;
					if (LOGICAL_OPERATORS.has(operator)) {
						cyclomatic++;
					}
				}

				// Track nesting for block-like structures
				if (depth > maxNesting) {
					maxNesting = depth;
				}
			});
		}

		return { name, line, cyclomatic, maxNesting, parameters: params };
	}

	/**
	 * Walk AST nodes counting nesting depth for complexity metrics
	 */
	private walkForComplexity(node: unknown, callback: (node: OxcNode, depth: number) => void, depth = 0): void {
		if (!node || typeof node !== "object") {
			return;
		}
		const n = node as OxcNode;
		if (typeof n.type !== "string") {
			return;
		}

		// Nesting-increasing nodes
		const nestingNodes = new Set([
			"IfStatement",
			"ForStatement",
			"ForInStatement",
			"ForOfStatement",
			"WhileStatement",
			"DoWhileStatement",
			"SwitchStatement",
			"TryStatement",
		]);

		const newDepth = nestingNodes.has(n.type) ? depth + 1 : depth;
		callback(n, newDepth);

		// Recurse into children
		for (const key of Object.keys(n)) {
			if (key === "type" || key === "start" || key === "end" || key === "loc") {
				continue;
			}
			const value = n[key];
			if (Array.isArray(value)) {
				for (const item of value) {
					this.walkForComplexity(item, callback, newDepth);
				}
			} else if (value && typeof value === "object" && typeof (value as OxcNode).type === "string") {
				this.walkForComplexity(value, callback, newDepth);
			}
		}
	}

	// -----------------------------------------------------------------------
	// Helpers
	// -----------------------------------------------------------------------

	private getFunctionName(node: OxcNode): string {
		// FunctionDeclaration / FunctionExpression
		if (node.id && typeof node.id === "object") {
			const id = node.id as OxcNode;
			if (typeof id.name === "string") {
				return id.name;
			}
		}

		// MethodDefinition
		if (node.key && typeof node.key === "object") {
			const key = node.key as OxcNode;
			if (typeof key.name === "string") {
				return key.name;
			}
			if (typeof key.value === "string") {
				return key.value;
			}
		}

		// ArrowFunctionExpression assigned to a variable
		// (parent context not available  -  return anonymous)
		return "<anonymous>";
	}

	private getParameterCount(node: OxcNode): number {
		if (node.type === "MethodDefinition") {
			const value = node.value as OxcNode | undefined;
			if (value && Array.isArray(value.params)) {
				return value.params.length;
			}
		}
		if (Array.isArray(node.params)) {
			return node.params.length;
		}
		return 0;
	}

	private getFunctionBody(node: OxcNode): OxcNode | null {
		if (node.type === "MethodDefinition") {
			const value = node.value as OxcNode | undefined;
			if (value?.body) {
				return value.body as OxcNode;
			}
		}
		if (node.body) {
			return node.body as OxcNode;
		}
		return null;
	}

	private shouldAnalyzeFile(file: string): boolean {
		const ext = file.split(".").pop()?.toLowerCase();
		return ["ts", "tsx", "js", "jsx", "mts", "cts"].includes(ext ?? "");
	}
}
