/**
 * Shared AST Parser Utility
 *
 * Wraps oxc-parser for high-performance TypeScript/JavaScript AST parsing.
 * oxc-parser is 3x faster than SWC and 5x faster than Biome (2026 benchmarks).
 * Outputs ESTree/TS-ESTree compatible AST for broad tooling compatibility.
 *
 * @module analysis/ast/parser
 */

import { parseSync as oxcParseSync } from "oxc-parser";

/** Supported source file extensions */
const TS_EXTENSIONS = new Set([".ts", ".tsx", ".mts", ".cts"]);
const JSX_EXTENSIONS = new Set([".tsx", ".jsx"]);
const ALL_EXTENSIONS = new Set([".ts", ".tsx", ".js", ".jsx", ".mts", ".cts", ".mjs", ".cjs"]);

/**
 * Result of parsing a source file
 */
export interface ParseResult {
	/** ESTree-compatible AST program node */
	program: OxcProgram;
	/** Parse errors (empty array if successful) */
	errors: OxcError[];
	/** Whether parsing succeeded without fatal errors */
	success: boolean;
}

/**
 * Minimal ESTree Program type from oxc-parser output
 */
export interface OxcProgram {
	type: "Program";
	body: OxcNode[];
	sourceType: "module" | "script";
	[key: string]: unknown;
}

/**
 * Generic ESTree node with a type discriminator
 */
export interface OxcNode {
	type: string;
	start?: number;
	end?: number;
	[key: string]: unknown;
}

/**
 * Parse error from oxc-parser
 */
export interface OxcError {
	message: string;
	severity: string;
	labels?: Array<{ span: { start: number; end: number } }>;
}

/**
 * Determine if a file path is a supported source file
 */
export function isSupportedFile(filePath: string): boolean {
	const ext = getExtension(filePath);
	return ALL_EXTENSIONS.has(ext);
}

/**
 * Parse a source file into an ESTree-compatible AST using oxc-parser.
 *
 * Uses synchronous parsing for maximum throughput (no async overhead).
 * Includes error recovery  -  partial ASTs are returned even with errors.
 *
 * @param content - Source code content
 * @param filePath - File path (used for language detection: TS/JSX)
 * @returns ParseResult with AST and any errors
 */
export function parseSource(content: string, filePath: string): ParseResult {
	const ext = getExtension(filePath);

	try {
		// oxc-parser API: parseSync(filename, sourceText, options?)
		const lang = JSX_EXTENSIONS.has(ext)
			? TS_EXTENSIONS.has(ext)
				? "tsx"
				: "jsx"
			: TS_EXTENSIONS.has(ext)
				? "ts"
				: "js";

		const result = oxcParseSync(filePath, content, {
			sourceType: "module",
			lang: lang as "ts" | "tsx" | "js" | "jsx",
		});

		const errors: OxcError[] = Array.isArray(result.errors)
			? result.errors.map((e: unknown) => normalizeError(e))
			: [];

		return {
			program: result.program as unknown as OxcProgram,
			errors,
			success: errors.length === 0,
		};
	} catch (error) {
		// Fatal parse failure  -  return empty program
		return {
			program: { type: "Program", body: [], sourceType: "module" },
			errors: [
				{
					message: error instanceof Error ? error.message : String(error),
					severity: "error",
				},
			],
			success: false,
		};
	}
}

/**
 * Simple recursive AST visitor.
 * Walks every node in the tree and calls the visitor function.
 */
export function walkAST(node: unknown, visitor: (node: OxcNode, parent?: OxcNode) => void, parent?: OxcNode): void {
	if (!node || typeof node !== "object") {
		return;
	}

	const n = node as OxcNode;

	// Only visit objects that look like AST nodes (have a 'type' string property)
	if (typeof n.type === "string") {
		visitor(n, parent);
	}

	// Recurse into all properties
	for (const key of Object.keys(n)) {
		if (key === "type" || key === "start" || key === "end" || key === "loc") {
			continue;
		}

		const value = n[key];
		if (Array.isArray(value)) {
			for (const item of value) {
				if (item && typeof item === "object" && typeof (item as OxcNode).type === "string") {
					walkAST(item, visitor, n);
				}
			}
		} else if (value && typeof value === "object" && typeof (value as OxcNode).type === "string") {
			walkAST(value, visitor, n);
		}
	}
}

/**
 * Count total AST nodes in a program
 */
export function countASTNodes(program: OxcProgram): number {
	let count = 0;
	walkAST(program, () => {
		count++;
	});
	return count;
}

/**
 * Convert character offset to 1-based line number (Task #11h)
 *
 * Used for mapping AST node positions (start/end offsets) to human-readable
 * line numbers in error messages. This is faster than regex-based approaches
 * and avoids expensive line splitting.
 *
 * @param source - Full source code string
 * @param offset - Character offset (0-based)
 * @returns 1-based line number
 *
 * @example
 * const line = offsetToLine("hello\nworld", 7); // returns 2
 */
export function offsetToLine(source: string, offset: number): number {
	if (offset < 0 || offset > source.length) {
		return 1;
	}

	let line = 1;
	for (let i = 0; i < offset; i++) {
		if (source[i] === "\n") {
			line++;
		}
	}
	return line;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function getExtension(filePath: string): string {
	const lastDot = filePath.lastIndexOf(".");
	return lastDot >= 0 ? filePath.substring(lastDot).toLowerCase() : "";
}

function normalizeError(e: unknown): OxcError {
	if (typeof e === "object" && e !== null) {
		const err = e as Record<string, unknown>;
		return {
			message: String(err.message ?? err),
			severity: String(err.severity ?? "error"),
			labels: Array.isArray(err.labels) ? err.labels : undefined,
		};
	}
	return { message: String(e), severity: "error" };
}
