/**
 * AST-based Import Extractor
 *
 * Replaces regex-based import extraction with proper AST walking.
 * Uses oxc-parser's ESTree output to accurately detect:
 * - Static imports (import ... from '...')
 * - Dynamic imports (import('...'))
 * - Re-exports (export ... from '...')
 * - CommonJS require() calls
 *
 * This eliminates false positives from strings/comments that look like imports.
 *
 * @module analysis/ast/import-extractor
 */

import { isSupportedFile, type OxcNode, parseSource, walkAST } from "./parser.js";

/**
 * A single import found in a source file
 */
export interface ImportInfo {
	/** The import source/specifier (e.g., './utils', 'react', '@vreko/core') */
	source: string;
	/** Type of import */
	kind: "static" | "dynamic" | "require" | "re-export";
	/** Whether this is a type-only import (import type { ... }) */
	typeOnly: boolean;
	/** Line number where the import appears */
	line?: number;
	/** Named specifiers imported (empty for namespace/default-only imports) */
	specifiers: string[];
}

/**
 * Result of extracting imports from a file
 */
export interface ImportExtractionResult {
	/** File path that was analyzed */
	filePath: string;
	/** All imports found */
	imports: ImportInfo[];
	/** Whether parsing succeeded */
	parseSuccess: boolean;
	/** Parse errors (if any) */
	parseErrors: string[];
}

/**
 * Extract all imports from a source file using AST analysis.
 *
 * @param content - Source code content
 * @param filePath - File path (for language detection)
 * @returns ImportExtractionResult with all found imports
 */
export function extractImports(content: string, filePath: string): ImportExtractionResult {
	if (!isSupportedFile(filePath)) {
		return {
			filePath,
			imports: [],
			parseSuccess: false,
			parseErrors: [`Unsupported file type: ${filePath}`],
		};
	}

	const { program, errors, success } = parseSource(content, filePath);
	const imports: ImportInfo[] = [];

	// Walk the AST to find all import-related nodes
	walkAST(program, (node: OxcNode) => {
		switch (node.type) {
			// import ... from 'source'
			case "ImportDeclaration":
				handleImportDeclaration(node, imports);
				break;

			// export { ... } from 'source'  OR  export * from 'source'
			case "ExportNamedDeclaration":
			case "ExportAllDeclaration":
				handleExportDeclaration(node, imports);
				break;

			// import('source')  -  ESTree ImportExpression
			case "ImportExpression":
				handleImportExpression(node, imports);
				break;

			// require('source')  OR  legacy import('source') as CallExpression
			case "CallExpression":
				handleCallExpression(node, imports);
				break;
		}
	});

	return {
		filePath,
		imports,
		parseSuccess: success,
		parseErrors: errors.map((e) => e.message),
	};
}

/**
 * Convenience: extract just the import source strings (deduplicated)
 */
export function extractImportSources(content: string, filePath: string): string[] {
	const result = extractImports(content, filePath);
	const sources = new Set<string>();
	for (const imp of result.imports) {
		sources.add(imp.source);
	}
	return [...sources];
}

/**
 * Batch extract imports from multiple files.
 * Useful for building dependency graphs efficiently.
 */
export function extractImportsBatch(files: Map<string, string>): Map<string, ImportExtractionResult> {
	const results = new Map<string, ImportExtractionResult>();
	for (const [filePath, content] of files) {
		results.set(filePath, extractImports(content, filePath));
	}
	return results;
}

// ---------------------------------------------------------------------------
// Node handlers
// ---------------------------------------------------------------------------

function handleImportDeclaration(node: OxcNode, imports: ImportInfo[]): void {
	const source = getStringValue(node.source);
	if (!source) {
		return;
	}

	const specifiers: string[] = [];
	if (Array.isArray(node.specifiers)) {
		for (const spec of node.specifiers) {
			const s = spec as OxcNode;
			if (s.type === "ImportSpecifier") {
				const imported = s.imported as OxcNode | undefined;
				specifiers.push(getIdentifierName(imported) ?? "unknown");
			} else if (s.type === "ImportDefaultSpecifier") {
				specifiers.push("default");
			} else if (s.type === "ImportNamespaceSpecifier") {
				specifiers.push("*");
			}
		}
	}

	imports.push({
		source,
		kind: "static",
		typeOnly: node.importKind === "type" || Boolean(node.isTypeOnly),
		line: node.start != null ? node.start : undefined,
		specifiers,
	});
}

function handleExportDeclaration(node: OxcNode, imports: ImportInfo[]): void {
	const source = getStringValue(node.source);
	if (!source) {
		return; // export without source (local export)
	}

	const specifiers: string[] = [];
	if (node.type === "ExportAllDeclaration") {
		specifiers.push("*");
	} else if (Array.isArray(node.specifiers)) {
		for (const spec of node.specifiers) {
			const s = spec as OxcNode;
			const local = s.local as OxcNode | undefined;
			specifiers.push(getIdentifierName(local) ?? "unknown");
		}
	}

	imports.push({
		source,
		kind: "re-export",
		typeOnly: node.exportKind === "type" || Boolean(node.isTypeOnly),
		line: node.start != null ? node.start : undefined,
		specifiers,
	});
}

function handleImportExpression(node: OxcNode, imports: ImportInfo[]): void {
	// oxc-parser ESTree: ImportExpression has .source directly
	const source = getStringValue(node.source);
	if (source) {
		imports.push({
			source,
			kind: "dynamic",
			typeOnly: false,
			line: node.start != null ? node.start : undefined,
			specifiers: [],
		});
	}
}

function handleCallExpression(node: OxcNode, imports: ImportInfo[]): void {
	const callee = node.callee as OxcNode | undefined;
	if (!callee) {
		return;
	}

	// Dynamic import: import('source')  -  fallback for non-ESTree parsers
	if (node.type === "CallExpression" && callee.type === "Import") {
		const args = node.arguments as OxcNode[] | undefined;
		if (args && args.length > 0) {
			const source = getStringValue(args[0]);
			if (source) {
				imports.push({
					source,
					kind: "dynamic",
					typeOnly: false,
					line: node.start != null ? node.start : undefined,
					specifiers: [],
				});
			}
		}
		return;
	}

	// require('source')
	if (callee.type === "Identifier" && callee.name === "require") {
		const args = node.arguments as OxcNode[] | undefined;
		if (args && args.length > 0) {
			const source = getStringValue(args[0]);
			if (source) {
				imports.push({
					source,
					kind: "require",
					typeOnly: false,
					line: node.start != null ? node.start : undefined,
					specifiers: [],
				});
			}
		}
	}
}

// ---------------------------------------------------------------------------
// Utility helpers
// ---------------------------------------------------------------------------

function getStringValue(node: unknown): string | undefined {
	if (!node || typeof node !== "object") {
		return undefined;
	}
	const n = node as OxcNode;
	if (n.type === "StringLiteral" || n.type === "Literal") {
		return typeof n.value === "string" ? n.value : undefined;
	}
	return undefined;
}

function getIdentifierName(node: unknown): string | undefined {
	if (!node || typeof node !== "object") {
		return undefined;
	}
	const n = node as OxcNode;
	if (n.type === "Identifier" || n.type === "IdentifierName" || n.type === "IdentifierReference") {
		return typeof n.name === "string" ? n.name : undefined;
	}
	return undefined;
}
