/**
 * Import Graph Analyzer
 *
 * AST-based analyzer that builds a file dependency graph and detects:
 * - Circular dependencies
 * - Orphan files (not imported by anything)
 * - High fan-in files (imported by too many files  -  fragility risk)
 * - High fan-out files (imports too many things  -  complexity risk)
 * - Cross-boundary imports (monorepo package boundary violations)
 *
 * Uses oxc-parser via the shared parser utility for maximum speed.
 * Replaces regex-based import extraction in intelligence/ast-analyzer.ts.
 *
 * @module analysis/ast/ImportGraphAnalyzer
 */

import { dirname, resolve } from "node:path";
import type { AnalysisContext, AnalysisIssue, Analyzer, AnalyzerResult } from "../types.js";
import { extractImports, type ImportExtractionResult } from "./import-extractor.js";

/** Thresholds for flagging issues */
const THRESHOLDS = {
	/** Max files that can import a single file before it's flagged as high fan-in */
	highFanIn: 15,
	/** Max imports a single file can have before it's flagged as high fan-out */
	highFanOut: 20,
	/** Minimum cycle length to report (avoids noise from self-imports) */
	minCycleLength: 2,
};

/**
 * A node in the import dependency graph
 */
export interface GraphNode {
	filePath: string;
	imports: string[];
	importedBy: string[];
	/** Type-only import sources (don't contribute to runtime coupling) */
	typeOnlyImports: string[];
}

/**
 * The full import graph for a set of files
 */
export interface ImportGraph {
	nodes: Map<string, GraphNode>;
	/** Forward edges: file → set of files it imports */
	edges: Map<string, Set<string>>;
	/** Reverse edges: file → set of files that import it */
	reverseEdges: Map<string, Set<string>>;
	/** Detected circular dependency cycles */
	cycles: string[][];
}

/**
 * AST-based import graph analyzer.
 * Implements the Analyzer interface for integration with the analysis pipeline.
 */
export class ImportGraphAnalyzer implements Analyzer {
	readonly id = "import-graph";
	readonly name = "Import Graph Analysis";
	readonly filePatterns = ["*.ts", "*.tsx", "*.js", "*.jsx"];

	async analyze(context: AnalysisContext): Promise<AnalyzerResult> {
		const startTime = performance.now();
		const issues: AnalysisIssue[] = [];
		let filesAnalyzed = 0;
		const parseErrors: string[] = [];

		// Step 1: Extract imports from all files via AST
		const extractions = new Map<string, ImportExtractionResult>();
		for (const [file, content] of context.contents) {
			if (!this.shouldAnalyzeFile(file)) {
				continue;
			}
			filesAnalyzed++;
			const result = extractImports(content, file);
			extractions.set(file, result);
			if (!result.parseSuccess) {
				parseErrors.push(...result.parseErrors);
			}
		}

		// Step 2: Build the import graph
		const graph = this.buildGraph(extractions, context.workspaceRoot);

		// Step 3: Detect circular dependencies
		const cycles = this.detectCycles(graph.edges);
		graph.cycles = cycles;

		for (const cycle of cycles) {
			issues.push({
				id: `import-graph/circular/${cycle.join("->")}`,
				severity: "high",
				type: "CIRCULAR_DEPENDENCY",
				message: `Circular dependency: ${cycle.join(" → ")}`,
				file: cycle[0],
				fix: "Break the cycle by extracting shared code or using dependency injection",
			});
		}

		// Step 4: Detect high fan-in (fragile hub files)
		for (const [file, node] of graph.nodes) {
			if (node.importedBy.length > THRESHOLDS.highFanIn) {
				issues.push({
					id: `import-graph/high-fan-in/${file}`,
					severity: "medium",
					type: "HIGH_FAN_IN",
					message: `${file} is imported by ${node.importedBy.length} files  -  changes here have high blast radius`,
					file,
					fix: "Consider splitting into smaller, more focused modules",
				});
			}
		}

		// Step 5: Detect high fan-out (overly coupled files)
		for (const [file, node] of graph.nodes) {
			const runtimeImports = node.imports.filter((imp) => !node.typeOnlyImports.includes(imp));
			if (runtimeImports.length > THRESHOLDS.highFanOut) {
				issues.push({
					id: `import-graph/high-fan-out/${file}`,
					severity: "low",
					type: "HIGH_FAN_OUT",
					message: `${file} imports ${runtimeImports.length} modules  -  high coupling`,
					file,
					fix: "Consider using a facade or consolidating related imports",
				});
			}
		}

		// Step 6: Detect orphan files (not imported by anything, not entry points)
		for (const [file, node] of graph.nodes) {
			if (node.importedBy.length === 0 && !this.isEntryPoint(file)) {
				issues.push({
					id: `import-graph/orphan/${file}`,
					severity: "info",
					type: "ORPHAN_FILE",
					message: `${file} is not imported by any other analyzed file`,
					file,
					fix: "Verify this file is needed  -  it may be dead code",
				});
			}
		}

		return {
			analyzer: this.id,
			success: true,
			issues,
			coverage: filesAnalyzed / Math.max(context.files.length, 1),
			duration: performance.now() - startTime,
			metadata: {
				filesAnalyzed,
				nodesVisited: graph.nodes.size,
				patternsChecked: ["CIRCULAR_DEPENDENCY", "HIGH_FAN_IN", "HIGH_FAN_OUT", "ORPHAN_FILE"],
				parseErrors,
			},
		};
	}

	shouldRun(context: AnalysisContext): boolean {
		return context.files.some((f) => this.shouldAnalyzeFile(f));
	}

	/**
	 * Build the import graph and return it for external consumption.
	 * Useful for other tools (momentum scoring, risk propagation, etc.).
	 */
	buildGraphFromContext(context: AnalysisContext): ImportGraph {
		const extractions = new Map<string, ImportExtractionResult>();
		for (const [file, content] of context.contents) {
			if (this.shouldAnalyzeFile(file)) {
				extractions.set(file, extractImports(content, file));
			}
		}
		const graph = this.buildGraph(extractions, context.workspaceRoot);
		graph.cycles = this.detectCycles(graph.edges);
		return graph;
	}

	// -----------------------------------------------------------------------
	// Graph construction
	// -----------------------------------------------------------------------

	private buildGraph(extractions: Map<string, ImportExtractionResult>, workspaceRoot: string): ImportGraph {
		const nodes = new Map<string, GraphNode>();
		const edges = new Map<string, Set<string>>();
		const reverseEdges = new Map<string, Set<string>>();

		// Initialize nodes for all analyzed files
		for (const filePath of extractions.keys()) {
			const normalized = this.normalizePath(filePath);
			nodes.set(normalized, {
				filePath: normalized,
				imports: [],
				importedBy: [],
				typeOnlyImports: [],
			});
			edges.set(normalized, new Set());
		}

		// Build edges from import data
		for (const [filePath, extraction] of extractions) {
			const normalized = this.normalizePath(filePath);

			for (const imp of extraction.imports) {
				const resolved = this.resolveImport(imp.source, filePath, workspaceRoot);
				if (!resolved) {
					continue;
				}

				const resolvedNorm = this.normalizePath(resolved);

				// Add forward edge
				edges.get(normalized)?.add(resolvedNorm);

				// Track in node
				const node = nodes.get(normalized);
				if (node && !node.imports.includes(resolvedNorm)) {
					node.imports.push(resolvedNorm);
					if (imp.typeOnly) {
						node.typeOnlyImports.push(resolvedNorm);
					}
				}

				// Add reverse edge (ensure target node exists)
				if (!reverseEdges.has(resolvedNorm)) {
					reverseEdges.set(resolvedNorm, new Set());
				}
				reverseEdges.get(resolvedNorm)?.add(normalized);

				// Ensure target node exists
				if (!nodes.has(resolvedNorm)) {
					nodes.set(resolvedNorm, {
						filePath: resolvedNorm,
						imports: [],
						importedBy: [],
						typeOnlyImports: [],
					});
				}
			}
		}

		// Populate importedBy from reverse edges
		for (const [file, importers] of reverseEdges) {
			const node = nodes.get(file);
			if (node) {
				node.importedBy = [...importers];
			}
		}

		return { nodes, edges, reverseEdges, cycles: [] };
	}

	// -----------------------------------------------------------------------
	// Cycle detection (Tarjan's SCC adapted for cycles)
	// -----------------------------------------------------------------------

	private detectCycles(edges: Map<string, Set<string>>): string[][] {
		const cycles: string[][] = [];
		const visited = new Set<string>();
		const inStack = new Set<string>();
		const stack: string[] = [];

		const dfs = (node: string): void => {
			if (inStack.has(node)) {
				// Found a cycle: extract it from the stack
				const cycleStart = stack.indexOf(node);
				if (cycleStart >= 0) {
					const cycle = stack.slice(cycleStart);
					if (cycle.length >= THRESHOLDS.minCycleLength) {
						cycles.push([...cycle, node]);
					}
				}
				return;
			}
			if (visited.has(node)) {
				return;
			}

			visited.add(node);
			inStack.add(node);
			stack.push(node);

			const neighbors = edges.get(node) ?? new Set();
			for (const neighbor of neighbors) {
				dfs(neighbor);
			}

			stack.pop();
			inStack.delete(node);
		};

		for (const node of edges.keys()) {
			dfs(node);
		}

		return cycles;
	}

	// -----------------------------------------------------------------------
	// Import resolution
	// -----------------------------------------------------------------------

	private resolveImport(importSource: string, fromFile: string, _workspaceRoot: string): string | null {
		// Skip external packages (bare specifiers)
		if (!importSource.startsWith(".") && !importSource.startsWith("/")) {
			// Handle workspace packages like @vreko/core
			if (importSource.startsWith("@")) {
				const parts = importSource.split("/");
				if (parts.length >= 2) {
					const pkg = parts[1];
					return `packages/${pkg}/src/index.ts`;
				}
			}
			return null;
		}

		// Resolve relative imports
		const fromDir = dirname(fromFile);
		let resolved = resolve(fromDir, importSource);

		// Add .ts extension if missing
		if (!resolved.match(/\.(ts|tsx|js|jsx|mts|cts|mjs|cjs)$/)) {
			resolved += ".ts";
		}

		// Strip .js → .ts for TypeScript projects (common pattern)
		resolved = resolved.replace(/\.js$/, ".ts").replace(/\.jsx$/, ".tsx");

		return resolved;
	}

	// -----------------------------------------------------------------------
	// Helpers
	// -----------------------------------------------------------------------

	private shouldAnalyzeFile(file: string): boolean {
		const ext = file.split(".").pop()?.toLowerCase();
		return ["ts", "tsx", "js", "jsx", "mts", "cts"].includes(ext ?? "");
	}

	private isEntryPoint(file: string): boolean {
		return (
			file.includes("index.") ||
			file.includes("main.") ||
			file.includes("entry.") ||
			file.includes("server.") ||
			file.includes("app.") ||
			file.endsWith("/page.tsx") ||
			file.endsWith("/layout.tsx") ||
			file.endsWith("/route.ts") ||
			file.includes("__tests__") ||
			file.includes(".test.") ||
			file.includes(".spec.")
		);
	}

	private normalizePath(filePath: string): string {
		return filePath.replace(/\\/g, "/").replace(/^\.\//, "");
	}
}
